import React, { useEffect, useMemo, useState } from 'react'
import { Link } from 'catalyst-core'
import manifest from '../../generated/docsManifest.json'
import { loadErrorsCatalog, groupByCategory } from '../../data/errorsCatalog'

/**
 * Hierarchical docs sidebar built from the manifest (which is already in
 * sidebar order). Mirrors Docusaurus's autogenerated sidebar: categories from
 * folder names, collapsible, current page highlighted.
 *
 * The "Error reference" group is the framework error catalog. It sits just
 * above the "MCP Integration" page (found by URL, not index, so it survives
 * manifest reordering). Its contents come from the live `errors/index.json`
 * fetch (see data/errorsCatalog.js), not the manifest — so on `/content/...`
 * pages, where no route fetcher has run, the catalog is lazy-loaded the first
 * time the group is expanded (post-hydration, cached, sentinel-safe). On
 * `/errors...` pages the page itself already has the data and passes it in via
 * `errorsCatalog`.
 */

const ERRORS_BASE = '/errors'
const MCP_URL = '/content/mcp-integration'

const buildTree = () => {
    const root = { label: null, items: [] }
    for (const page of manifest) {
        let node = root
        for (const category of page.categories) {
            let child = node.items.find(
                (item) =>
                    item.type === 'category' && item.node.label === category
            )?.node
            if (!child) {
                child = { label: category, items: [] }
                node.items.push({ type: 'category', node: child })
            }
            node = child
        }
        node.items.push({ type: 'page', page })
    }
    return root
}

const Caret = ({ open }) => (
    <span className={`docs-sidebar-caret ${open ? 'open' : ''}`} aria-hidden="true">
        <svg
            viewBox="0 0 24 24"
            fill="none"
            stroke="currentColor"
            strokeWidth="2.4"
            strokeLinecap="round"
            strokeLinejoin="round"
        >
            <path d="m9 5 7 7-7 7" />
        </svg>
    </span>
)

const Category = ({ node, currentUrl, depth }) => {
    const containsCurrent = useMemo(() => {
        const scan = (candidate) =>
            candidate.items.some((item) =>
                item.type === 'page'
                    ? item.page.url === currentUrl
                    : scan(item.node)
            )
        return scan(node)
    }, [node, currentUrl])

    const [open, setOpen] = useState(containsCurrent)

    return (
        <div className={`docs-sidebar-category depth-${depth}`}>
            <button
                className={`docs-sidebar-category-label ${containsCurrent ? 'active-trail' : ''}`}
                onClick={() => setOpen(!open)}
                aria-expanded={open}
            >
                <Caret open={open} />
                {node.label}
            </button>
            {open && (
                <TreeLevel
                    node={node}
                    currentUrl={currentUrl}
                    depth={depth + 1}
                />
            )}
        </div>
    )
}

const TreeLevel = ({ node, currentUrl, depth }) => (
    <div className="docs-sidebar-level">
        {node.items.map((item) =>
            item.type === 'page' ? (
                <Link
                    key={item.page.url}
                    to={item.page.url}
                    className={`docs-sidebar-link ${item.page.url === currentUrl ? 'active' : ''}`}
                >
                    {item.page.sidebarLabel}
                </Link>
            ) : (
                <Category
                    key={item.node.label}
                    node={item.node}
                    currentUrl={currentUrl}
                    depth={depth}
                />
            )
        )}
    </div>
)

/**
 * One error category (e.g. "PREFLIGHT") — expands to its codes. Each code's
 * sidebar label is its human message, not the code string, so a developer
 * scans by meaning. The code still headlines the page it links to.
 */
const ErrorCategory = ({ category, codes, catalog, currentCode, depth }) => {
    const containsCurrent = codes.includes(currentCode)
    const [open, setOpen] = useState(containsCurrent)

    return (
        <div className={`docs-sidebar-category depth-${depth}`}>
            <button
                className={`docs-sidebar-category-label ${containsCurrent ? 'active-trail' : ''}`}
                onClick={() => setOpen(!open)}
                aria-expanded={open}
            >
                <Caret open={open} />
                {category}
            </button>
            {open && (
                <div className="docs-sidebar-level">
                    {codes.map((code) => (
                        <Link
                            key={code}
                            to={`${ERRORS_BASE}/${category}/${code}`}
                            className={`docs-sidebar-link docs-sidebar-link-truncate ${code === currentCode ? 'active' : ''}`}
                            title={`${code} — ${catalog[code].message}`}
                        >
                            {catalog[code].message}
                        </Link>
                    ))}
                </div>
            )}
        </div>
    )
}

/**
 * The "Error reference" group. Clicking the label navigates to /errors AND
 * toggles the tree (consistent with how other categories toggle on click); the
 * caret toggles expansion in place without navigating. `catalog` is passed in
 * on /errors pages; on other pages it's fetched on first expand.
 */
const ErrorReferenceGroup = ({ currentUrl, errorsCatalog }) => {
    const onErrorsPage = currentUrl.startsWith(ERRORS_BASE)
    const [open, setOpen] = useState(onErrorsPage)
    const [fetched, setFetched] = useState(null)

    const catalog = errorsCatalog || fetched

    useEffect(() => {
        if (!open || catalog) return
        let cancelled = false
        loadErrorsCatalog().then((res) => {
            if (!cancelled && res.ok) setFetched(res.data)
        })
        return () => {
            cancelled = true
        }
    }, [open, catalog])

    const currentCode = useMemo(() => {
        const m = currentUrl.match(/^\/errors\/[^/]+\/([^/]+)$/)
        return m ? m[1] : null
    }, [currentUrl])

    const groups = useMemo(
        () => (catalog ? groupByCategory(catalog) : []),
        [catalog]
    )

    return (
        <div className="docs-sidebar-category depth-0">
            <div
                className={`docs-sidebar-grouphead ${onErrorsPage ? 'active-trail' : ''}`}
            >
                <button
                    type="button"
                    className="docs-sidebar-caret-btn"
                    aria-label={`${open ? 'Collapse' : 'Expand'} Error reference`}
                    aria-expanded={open}
                    onClick={() => setOpen(!open)}
                >
                    <Caret open={open} />
                </button>
                <Link
                    to={ERRORS_BASE}
                    className={`docs-sidebar-link docs-sidebar-grouplink ${currentUrl === ERRORS_BASE ? 'active' : ''}`}
                    onClick={() => setOpen((v) => !v)}
                >
                    Error reference
                </Link>
            </div>
            {open && (
                <div className="docs-sidebar-level">
                    {catalog ? (
                        groups.map(({ category, codes }) => (
                            <ErrorCategory
                                key={category}
                                category={category}
                                codes={codes}
                                catalog={catalog}
                                currentCode={currentCode}
                                depth={1}
                            />
                        ))
                    ) : (
                        <div className="errors-sidebar-skeleton" aria-hidden="true">
                            {Array.from({ length: 6 }).map((_, i) => (
                                <div key={i} className="errors-skeleton-row" />
                            ))}
                        </div>
                    )}
                </div>
            )}
        </div>
    )
}

const DocsSidebar = ({ currentUrl, mobileOpen, onClose, errorsCatalog }) => {
    const tree = useMemo(buildTree, [])

    // Error reference sits just above the MCP Integration page. Split the
    // top-level items there; append if MCP isn't in the manifest.
    const { before, after } = useMemo(() => {
        const idx = tree.items.findIndex(
            (it) => it.type === 'page' && it.page.url === MCP_URL
        )
        if (idx === -1) return { before: tree.items, after: [] }
        return { before: tree.items.slice(0, idx), after: tree.items.slice(idx) }
    }, [tree])

    return (
        <>
            {mobileOpen && (
                <div
                    className="docs-sidebar-backdrop"
                    onClick={onClose}
                    role="presentation"
                />
            )}
            <aside className={`docs-sidebar ${mobileOpen ? 'mobile-open' : ''}`}>
                <TreeLevel
                    node={{ items: before }}
                    currentUrl={currentUrl}
                    depth={0}
                />
                <ErrorReferenceGroup
                    currentUrl={currentUrl}
                    errorsCatalog={errorsCatalog}
                />
                {after.length > 0 && (
                    <TreeLevel
                        node={{ items: after }}
                        currentUrl={currentUrl}
                        depth={0}
                    />
                )}
            </aside>
        </>
    )
}

export default DocsSidebar
